def scale_pixmap_cover(pixmap, target_width, target_height):
    """
    Scale a pixmap to completely fill a target_width x target_height box
    with no distortion (aspect ratio preserved) and no empty space,
    center-cropping whatever overhangs. This is what lets images of any
    aspect ratio (portrait, landscape, near-square, ...) all look
    consistent as a background.
    """
    if pixmap.isNull() or target_width <= 0 or target_height <= 0:
        return pixmap

    # Scale up so the *smaller* dimension matches the target (this is what
    # overfills the other dimension instead of leaving letterbox gaps).
    scaled = pixmap.scaled(
        target_width,
        target_height,
        QtCore.Qt.KeepAspectRatioByExpanding,
        QtCore.Qt.SmoothTransformation
    )

    # Center-crop the overhang so the result is exactly target_width x target_height.
    x = max(0, (scaled.width() - target_width) // 2)
    y = max(0, (scaled.height() - target_height) // 2)

    return scaled.copy(x, y, target_width, target_height)


def darken_color(hex_color, factor=0.6):
    """Darken a hex color by multiplying RGB values by factor (0-1)."""
    hex_color = hex_color.lstrip('#')
    r = int(hex_color[0:2], 16)
    g = int(hex_color[2:4], 16)
    b = int(hex_color[4:6], 16)

    r = max(0, int(r * factor))
    g = max(0, int(g * factor))
    b = max(0, int(b * factor))

    return f"#{r:02x}{g:02x}{b:02x}"


def set_background(ui, name_of_background, pokemon_type=None):
    print(name_of_background)

    # NOTE: this is called from retranslateUi(), which runs during
    # setupUi() -- before the window is ever shown. At that point Qt
    # hasn't laid out centralwidget against the QMainWindow yet, so
    # centralwidget.width()/height() would return Qt's default new-widget
    # size (100x30), not the real window size. Since this window is a
    # fixed-size, absolute-positioned layout (see Top10.resize(645, 595)
    # above), we use the same known design size here instead of querying
    # live (and, at this point, unreliable) widget geometry.
    widget_width = 651
    widget_height = 561

    # Make all labels black
    ui.centralwidget.setStyleSheet("""
        QLabel {
            color: black;
            font-weight: bold;

        }
    """)

    # Background
    ui.background.setGeometry(0, 0, widget_width, widget_height)

    # If type provided, use darkened type color; otherwise use background image
    if pokemon_type and pokemon_type in TYPE_COLORS:
        background_color = darken_color(TYPE_COLORS[pokemon_type], factor=0.6)
        # Clear any existing pixmap first
        ui.background.setPixmap(QtGui.QPixmap())
        ui.background.setStyleSheet(f"background-color: {background_color};")
        # Delete overlay if it exists
        if hasattr(ui, 'background_overlay') and ui.background_overlay is not None:
            try:
                ui.background_overlay.deleteLater()
            except RuntimeError:
                pass
            ui.background_overlay = None
    else:
        # Load default background image with overlay baked in
        ui.background.setStyleSheet("")  # Clear stylesheet
        pixmap = QtGui.QPixmap("img/poke_background.jpg")
        pixmap = scale_pixmap_cover(pixmap, widget_width, widget_height)

        # Create overlay painter on the pixmap
        painter = QtGui.QPainter(pixmap)
        painter.fillRect(pixmap.rect(), QtGui.QColor(255, 255, 255, 150))
        painter.end()

        ui.background.setPixmap(pixmap)

        # Delete old overlay if it exists
        if hasattr(ui, 'background_overlay') and ui.background_overlay is not None:
            try:
                ui.background_overlay.deleteLater()
            except RuntimeError:
                pass
            ui.background_overlay = None

    # Put background at the very back
    ui.background.lower()

    # Delete old overlay if it exists
    if hasattr(ui, 'background_overlay') and ui.background_overlay is not None:
        ui.background_overlay.deleteLater()

    ui.search_box.raise_()
    ui.type_label.raise_()
    ui.type.raise_()

    ui.card.raise_()
    ui.type_header.raise_()
    ui.divider.raise_()
