def handle_top(ui, pokedex, on_pokemon_click=None):

    # Get the value from the LineEdit
    type_name = ui.type.text()
    ui.type.clear()

    print("User entered: ", type_name)

    # Get Pokemon from database
    top10 = pokedex.get_top_10(type_name)

    if top10 is None:
        ui.type_header.setText("Type Not Found")
        return

    print(top10)

    name_of_background = type_name.lower() + ".jpg"
    set_background(ui, name_of_background, pokemon_type=type_name.lower())

    # Type badge + card border themed to the searched type
    color = TYPE_COLORS.get(type_name.lower(), DEFAULT_TYPE_COLOR)
    ui.type_header.setText(type_name.capitalize())
    ui.type_header.setStyleSheet(
        f"background-color: {color};"
        "color: white;"
        "font-weight: bold;"
        "font-size: 11pt;"
        "border-radius: 14px;"
        "padding: 2px;"
    )
    ui.card.setStyleSheet(
        "QFrame#card {"
        "background-color: rgba(255, 255, 255, 235);"
        f"border: 5px solid {color};"
        "border-radius: 22px;"
        "}"
    )

    # Search box matches the card border color
    ui.search_box.setStyleSheet(
        "QFrame#search_box {"
        f"background-color: {color};"
        "border-radius: 12px;"
        "}"
    )

    # Results, ranked 1-10 (previously pokemon2 accidentally showed a
    # weight value instead of the Pokemon's name -- fixed here)
    names = top10["pokemon"]
    for i in range(10):
        rank = i + 1
        pokemon_name = str(names[i]).lower()
        pokemon_display_name = str(names[i]).title()

        # Name button (clickable)
        name_btn = getattr(ui, f"pokemon{rank}")
        name_btn.setText(f"{rank}. {pokemon_display_name}")
        try:
            name_btn.clicked.disconnect()
        except TypeError:
            pass
        if on_pokemon_click:
            name_btn.clicked.connect(lambda checked, pname=pokemon_name: on_pokemon_click(pname))
        else:
            name_btn.clicked.connect(lambda checked, pname=pokemon_name, pui=ui, pdb=pokedex: _lookup_pokemon_top10(pui, pdb, pname))

        # Sprite button (clickable)
        sprite_btn = getattr(ui, f"sprite{rank}")
        try:
            sprite_btn.clicked.disconnect()
        except TypeError:
            pass
        if on_pokemon_click:
            sprite_btn.clicked.connect(lambda checked, pname=pokemon_name: on_pokemon_click(pname))
        else:
            sprite_btn.clicked.connect(lambda checked, pname=pokemon_name, pui=ui, pdb=pokedex: _lookup_pokemon_top10(pui, pdb, pname))

        # Get sprite from database
        conn = pokedex.get_connection()
        cursor = conn.cursor()
        cursor.execute("SELECT sprite, type_1, type_2 FROM pokedex WHERE LOWER(pokemon) = ?", (pokemon_name,))
        row = cursor.fetchone()
        conn.close()

        if row and row[0]:
            sprite_data = row[0]
            pixmap = QtGui.QPixmap()
            pixmap.loadFromData(sprite_data)
            if not pixmap.isNull():
                scaled = pixmap.scaled(32, 32, QtCore.Qt.KeepAspectRatio, QtCore.Qt.SmoothTransformation)
                icon = QtGui.QIcon(scaled)
                sprite_btn.setIcon(icon)
                sprite_btn.setIconSize(QtCore.QSize(32, 32))

        # Get type info
        if row:
            type_1 = row[1]
            type_2 = row[2]
            type_badge = getattr(ui, f"type{rank}")
            type_badge2 = getattr(ui, f"type{rank}_2")

            if type_1:
                type_color = TYPE_COLORS.get(str(type_1).lower(), DEFAULT_TYPE_COLOR)
                type_badge.setText(str(type_1).capitalize())
                type_badge.setStyleSheet(
                    f"font-size: 8pt; font-weight: bold; border-radius: 4px; padding: 2px; "
                    f"background-color: {type_color}; color: white;"
                )

            if type_2 and pd.notna(type_2):
                type_color2 = TYPE_COLORS.get(str(type_2).lower(), DEFAULT_TYPE_COLOR)
                type_badge2.setText(str(type_2).capitalize())
                type_badge2.setStyleSheet(
                    f"font-size: 8pt; font-weight: bold; border-radius: 4px; padding: 2px; "
                    f"background-color: {type_color2}; color: white;"
                )
                type_badge2.show()
            else:
                type_badge2.hide()

        # Get and display total stats
        total_stats = top10.iloc[i].get('total_stats', 0)
        stats_label = getattr(ui, f"stats{rank}")
        stats_label.setText(f"Total: {int(total_stats)}")


def _lookup_pokemon_top10(ui, pokedex, pokemon_name):
    """Look up a pokemon from top 10 click and display it in lookup window."""
    # Import here to avoid circular import at module load time
    import look_up

    poke_data = pokedex.get_pokemon_by_name(pokemon_name)

    if poke_data is None:
        return

    # Use the lookup function to display the pokemon
    look_up._lookup_pokemon_by_name(ui, pokedex, pokemon_name)
